package com.jadhavr.erp.academic.controller;
import com.jadhavr.erp.academic.dto.AcademicDtos.*; import com.jadhavr.erp.academic.service.AcademicService; import com.jadhavr.erp.common.api.ApiResponse; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/academic") public class AcademicController { private final AcademicService service; public AcademicController(AcademicService s){service=s;}
 @PostMapping("/classes") public ApiResponse<?> createClass(@Valid @RequestBody CreateClass r){return ApiResponse.success("Academic class created",service.createClass(r));} @GetMapping("/classes/search") public ApiResponse<?> classes(@RequestParam(required=false)Long departmentId){return ApiResponse.success("Academic classes",service.classes(departmentId));} @PatchMapping("/classes/{id}/activate") public ApiResponse<?> activateClass(@PathVariable Long id){return ApiResponse.success("Class activated",service.classStatus(id,true));} @PatchMapping("/classes/{id}/deactivate") public ApiResponse<?> deactivateClass(@PathVariable Long id){return ApiResponse.success("Class deactivated",service.classStatus(id,false));}
 @PostMapping("/sections") public ApiResponse<?> createSection(@Valid @RequestBody CreateSection r){return ApiResponse.success("Section created",service.createSection(r));} @GetMapping("/sections/search") public ApiResponse<?> sections(@RequestParam(required=false)Long classId){return ApiResponse.success("Sections",service.sections(classId));} @PatchMapping("/sections/{id}/assign-class-teacher") public ApiResponse<?> assignClassTeacher(@PathVariable Long id,@Valid @RequestBody Assign r){return ApiResponse.success("Class teacher assigned",service.assignClassTeacher(id,r));} @PreAuthorize("hasRole('HOD')") @PostMapping("/sections/{id}/students") public ApiResponse<?> assignStudent(@PathVariable Long id,@Valid @RequestBody AssignStudent r){return ApiResponse.success("Student assigned",service.assignStudent(id,r));} @PreAuthorize("hasRole('HOD')") @GetMapping("/classes/{id}/eligible-students") public ApiResponse<?> eligibleStudents(@PathVariable Long id){return ApiResponse.success("Eligible students",service.eligibleStudents(id));} @GetMapping("/sections/{id}/students") public ApiResponse<?> sectionStudents(@PathVariable Long id){return ApiResponse.success("Class roster",service.sectionStudents(id));} @GetMapping("/class-teacher/my-class") public ApiResponse<?> classTeacherRoster(){return ApiResponse.success("My class roster",service.classTeacherRoster());}
 @PostMapping("/subjects") public ApiResponse<?> createSubject(@Valid @RequestBody CreateSubject r){return ApiResponse.success("Subject created",service.createSubject(r));} @PutMapping("/subjects/{id}") public ApiResponse<?> updateSubject(@PathVariable Long id,@Valid @RequestBody UpdateSubject r){return ApiResponse.success("Subject updated",service.updateSubject(id,r));} @DeleteMapping("/subjects/{id}") public ApiResponse<?> deleteSubject(@PathVariable Long id){service.deleteSubject(id);return ApiResponse.success("Subject deleted",null);} @GetMapping("/subjects/search") public ApiResponse<?> subjects(@RequestParam(required=false)Long classId,@RequestParam(required=false)Long departmentId,@RequestParam(required=false)String yearName){return ApiResponse.success("Subjects",service.subjects(classId,departmentId,yearName));} @PreAuthorize("hasRole('HOD')") @PostMapping("/subjects/{id}/assign-teacher") public ApiResponse<?> assignTeacher(@PathVariable Long id,@Valid @RequestBody Assign r){return ApiResponse.success("Subject teacher assigned",service.assignTeacher(id,r));} @PreAuthorize("hasRole('HOD')") @DeleteMapping("/subjects/{subjectId}/unassign-teacher/{teacherId}") public ApiResponse<?> unassignTeacher(@PathVariable Long subjectId,@PathVariable Long teacherId){service.unassignTeacher(subjectId,teacherId);return ApiResponse.success("Teacher unassigned from subject",null);} @GetMapping("/subject-teacher-assignments") public ApiResponse<?> listAssignments(@RequestParam(required=false)Long teacherId,@RequestParam(required=false)Long subjectId){return ApiResponse.success("Subject-teacher assignments",service.listAssignments(teacherId,subjectId));}
 @PostMapping("/timetable") public ApiResponse<?> timetable(@Valid @RequestBody CreateTimetable r){return ApiResponse.success("Timetable entry created",service.createTimetable(r));} @GetMapping("/timetable") public ApiResponse<?> timetable(@RequestParam Long sectionId){return ApiResponse.success("Timetable",service.timetable(sectionId));}
 @PostMapping("/attendance/sessions") public ApiResponse<?> attendance(@Valid @RequestBody CreateAttendance r){return ApiResponse.success("Attendance session created",service.createAttendance(r));} @PatchMapping("/attendance/sessions/{id}/mark") public ApiResponse<?> mark(@PathVariable Long id,@Valid @RequestBody Mark r){return ApiResponse.success("Attendance saved",service.mark(id,r));} @PatchMapping("/attendance/sessions/{id}/submit") public ApiResponse<?> submit(@PathVariable Long id){return ApiResponse.success("Attendance submitted",service.submit(id));} @GetMapping("/attendance/students/{id}/summary") public ApiResponse<?> summary(@PathVariable Long id){return ApiResponse.success("Attendance summary",service.attendanceSummary(id));}
}
